python
def ribbonRunsProofStrip(line):
    a=line
    out=[]
    i=0
    while i<len(a):
        j=i+1
        while j<len(a) and a[j]==a[i]: j+=1
        out.append(j-i)
        i=j
    return out


java
class Solution {
  public int[] ribbonRunsProofStrip(String line) {
    String a=line; List<Integer> out=new ArrayList<>();
    {for(int i=0;i<a.length();){int j=i+1;while(j<a.length()&&a.charAt(j)==a.charAt(i))j++;out.add(j-i);i=j;}}
    return out.stream().mapToInt(Integer::intValue).toArray();
  }
}
